export const widgetKinds=['Current book','Today’s page','Quick capture','Writing time','Bookshelf'];
export const readingFonts={'Lora':'Lora,Georgia,serif','Literata':'Literata,Georgia,serif','Source Serif':'SourceSerif,Georgia,serif','DM Sans':'"DM Sans",sans-serif','IBM Plex':'IBMPlex,sans-serif','System':'system-ui,sans-serif'};
export function widgetSnapshot(state,p,today){return {snapshotAt:Date.now(),title:state.settings.widgetTitles&&p?p.title:'Your writing room',wordCount:p&&!p.sample?p.chapters.reduce((n,c)=>n+(c.text.replace(/<[^>]*>/g,' ').trim().match(/\S+/g)||[]).length,0):0,today:state.activity[today]||0,goal:state.settings.dailyGoal||500,books:state.projects.filter(p=>!p.archived&&!p.sample).length,chapters:state.projects.filter(p=>!p.sample).reduce((n,p)=>n+p.chapters.filter(c=>c.text?.trim()).length,0),sessionEndsAt:state.writingSession&&!state.writingSession.finished?state.writingSession.endsAt:0};}
